///|
async test "review evidence hides ssh agent path" {
  let socket = "/tmp/fixture-agent/socket"
  let environment : Map[String, String] = {
    "PATH": "/usr/bin:/bin",
    "SSH_AUTH_SOCK": socket,
  }
  let (status, _, detail) = command_result(
    "/bin/sh",
    ["-c", "printf 'ssh agent socket /tmp/fixture-agent/socket unavailable\\n' >&2; exit 9"],
    "review-ssh-agent",
    environment~,
  )
  assert_eq(status, 9)
  assert_true(detail.contains("ssh agent socket"), msg=detail)
  assert_true(detail.contains("[redacted]"), msg=detail)
  assert_false(detail.contains(socket), msg=detail)
}

///|
async test "review command executable not recorded" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  let commands = [directory + "/bin/devsy-a", directory + "/bin/devsy-b"]
  for executable in commands {
    @fs.write_file(executable, "#!/bin/sh\nprintf 'same context failure\\n' >&2\nexit 7\n", permission=0o700)
    @fs.write_file(directory + "/orca.yaml", "devsy: {connection: ssh, buildRef: refs/heads/main, command: ['" + executable + "']}\nenvironmentRecipes: [{id: test}]\n")
    let (status, _, _) = invoke("create", env, directory)
    assert_true(status != 0)
  }
  let events = fixture_events(directory)
  let all = Json::array(events).stringify()
  for executable in commands {
    assert_false(all.contains(executable), msg=all)
  }
  let failed = events.filter(event => field(event, "stage") == Some(Json::string("resolve-context")) && field(event, "status") == Some(Json::string("exit-error")))
  assert_eq(failed.length(), 2)
  assert_eq(field(failed[0], "exitCode"), field(failed[1], "exitCode"))
  assert_eq(field(failed[0], "errorMessage"), field(failed[1], "errorMessage"))
}

///|
async test "review combined settings failure claims complete after truncation" {
  let environment : Map[String, String] = { "PATH": "/usr/bin:/bin" }
  let payload : Json = {
    "phase": "write",
    "code": "ENOSPC",
    "kind": "Error",
    "message": "m".repeat(600),
    "path": "/tmp/" + "p".repeat(600),
  }
  let shell = "printf %s " + quote(payload.stringify()) + " >&2; exit 1"
  let detail = try {
    ignore(settings_process("/bin/sh", ["-c", shell], environment~))
    None
  } catch {
    SettingsProcessError(_, _, _, value) => value
    error => raise error
  }
  guard detail is Some(detail) else { fail("missing settings detail") }
  assert_true(detail.length() > 1024)
  save_diagnostic("review-settings", "failed", error_type="ENOSPC", error_message=detail)
  finish_diagnostic_recording()
  let root = adapter_state_home()
  let events : Array[Json] = @fs.read_file(root + "/events.jsonl").text().split("\n").to_array().filter(line => line != "").map(line => @json.parse(line.to_owned()))
  let failure = events.filter(event => field(event, "stage") == Some(Json::string("review-settings")))
